package ncasa.expense.application.settlement;
import java.time.Clock;import java.util.UUID;import ncasa.expense.application.*;import ncasa.expense.application.port.out.*;import ncasa.expense.domain.*;
public final class VoidSettlementUseCase {private final SettlementRepository r;private final HouseholdExpenseAccessPort a;private final Clock c;public VoidSettlementUseCase(SettlementRepository r,HouseholdExpenseAccessPort a,Clock c){this.r=r;this.a=a;this.c=c;}public SettlementView execute(Long actor,UUID householdId,UUID id,String reason){var h=new HouseholdRef(householdId);var context=a.getContext(h,actor);var settlement=r.findByIdAndHousehold(new SettlementId(id),h).orElseThrow(SettlementNotFoundException::new);if(!context.administrator()&&!context.actorMemberId().equals(settlement.createdByMemberId()))throw new ExpenseAccessDeniedException("Only the creator or an administrator can void a settlement");settlement.voidSettlement(reason,c.instant());return SettlementView.from(r.save(settlement,null));}}
